/* tabs */
.tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 18px;
}
.tab {
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--muted);
  border-radius: 10px;
  padding: 9px 16px;
  cursor: pointer;
  font-size: 13.5px;
  transition: 0.15s ease;
}
.tab:hover { color: var(--text); border-color: #3c5573; }
.tab.active {
  background: linear-gradient(145deg, #2f8a55, #1f6b3f);
  border-color: #3aa469;
  color: #f2fff7;
  font-weight: 600;
}

/* research charts */
.charts {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 13px;
}
.chart-card {
  background: linear-gradient(180deg, rgba(23, 33, 49, 0.95), rgba(18, 25, 38, 0.95));
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 14px 16px;
  overflow: hidden;
}
.chart-card h2 {
  margin: 0 0 10px;
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.6px;
}
.chart-card canvas { display: block; }

.notice {
  margin-top: 26px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.7;
  border-top: 1px solid var(--line);
  padding-top: 14px;
}

