def set_impact(injury_id: int, body: ImpactIn, conn: sqlite3.Connection = Depends(get_conn)) -> dict:
    conn.execute("UPDATE injuries SET impact=? WHERE id=?", (body.impact, injury_id))
    conn.commit()
