import json
import urllib.request

BASE = "http://127.0.0.1:8010"


def get(path):
    with urllib.request.urlopen(BASE + path, timeout=30) as r:
        return r.status, r.read()


d = json.loads(get("/api/games?date=2026-11-04")[1])
games = d.get("games", d if isinstance(d, list) else [])
print("games:", len(games))
sig = bet = gated = 0
for g in games:
    for e in g.get("edges") or []:
        if e.get("signal"):
            sig += 1
        if e.get("bettable"):
            bet += 1
        if e.get("gated"):
            gated += 1
    if g.get("prediction", {}).get("details", {}).get("divergence_risk") is None and g.get("edges"):
        pass
print(f"signals={sig} bettable={bet} gated={gated}")

emp = [g for g in games if not g["edges"]]
print("games with no odds:", len(emp))
print("consensus sample:", json.dumps((games[0].get("prediction") or {}).get("details", {}).get("consensus"), ensure_ascii=False))
print("divergence_risk sample:", (games[0].get("prediction") or {}).get("details", {}).get("divergence_risk"))

for p in ("/api/linemove", "/api/holdout", "/api/trends"):
    st, body = get(p)
    print(p, st, len(body))

