const r = await fetch("https://site.api.espn.com/apis/site/v2/sports/basketball/nba/summary?event=401909929&lang=zh", {headers: {"User-Agent": "nbaq-check"}});
const j = await r.json();
const chineseSamples = [];
const walk = (o, path="") => {
  if (!o || typeof o !== "object") return;
  if (Array.isArray(o)) { o.forEach((v,i)=>walk(v, path+"["+i+"]")); return; }
  for (const [k,v] of Object.entries(o)) {
    if (typeof v === "string" && /[\u4e00-\u9fa5]/.test(v) && chineseSamples.length < 25) chineseSamples.push({path: path+"."+k, v});
    else if (typeof v === "object") walk(v, path+"."+k);
  }
};
walk(j);
return {
  hasInjuries: !!j.injuries,
  injCount: j.injuries?.length,
  firstInjury: j.injuries?.[0],
  chineseSamples,
  teams: j.boxscore?.teams?.map(t=>t.team?.displayName)
};

