101: const ESPN_SCOREBOARD = "https://site.api.espn.com/apis/site/v2/sports/basketball/nba/scoreboard";
102: const ESPN_SUMMARY = "https://site.api.espn.com/apis/site/v2/sports/basketball/nba/summary";
103: const PERIOD_SECONDS = 720;
104: const OT_SECONDS = 300;
105: const REGULATION_SECONDS = 4 * PERIOD_SECONDS;
106: 
107: function jsGameSeconds(period, clockSeconds) {
108:   period = period || 0;
109:   const clock = Math.max(clockSeconds || 0, 0);
110:   if (period <= 4) return (period - 1) * PERIOD_SECONDS + (PERIOD_SECONDS - clock);
111:   return REGULATION_SECONDS + (period - 5) * OT_SECONDS + (OT_SECONDS - clock);
112: }
113: 
114: function jsFractionPlayed(period, clockSeconds) {
115:   return Math.min(Math.max(jsGameSeconds(period, clockSeconds) / REGULATION_SECONDS, 0), 1);
116: }
117: 
118: // 标准正态分布 CDF（Abramowitz-Stegun 近似，精度足够 UI 用）
119: function jsNormalCdf(x) {
120:   const t = 1 / (1 + 0.2316419 * Math.abs(x));
121:   const poly =
122:     t * (0.319381530 + t * (-0.356563782 + t * (1.781477937 + t * (-1.821255978 + t * 1.330274429))));
123:   const cdf = 1 - (Math.exp((-x * x) / 2) / Math.sqrt(2 * Math.PI)) * poly;
124:   return x >= 0 ? cdf : 1 - cdf;
125: }
126: 
127: function jsLiveProjection(pregame, period, clockSeconds, currentMargin, currentTotal) {
128:   const remainingFactor = 1 - jsFractionPlayed(period, clockSeconds);
129:   const played = jsGameSeconds(period, clockSeconds);
130:   const sigmaFactor = Math.max(Math.pow((REGULATION_SECONDS - played) / REGULATION_SECONDS, 0.5), 0.05);
131:   const projMargin = currentMargin + pregame.pred_margin * remainingFactor;
132:   const projTotal = currentTotal + pregame.pred_total * remainingFactor;
133:   const sigmaM = Math.max(pregame.sigma_margin * sigmaFactor, 1.0);
134:   const sigmaT = Math.max(pregame.sigma_total * sigmaFactor, 1.5);
135:   return {
136:     proj_margin: projMargin,
137:     proj_total: projTotal,
138:     sigma_margin: sigmaM,
139:     sigma_total: sigmaT,
140:     home_win_prob: jsNormalCdf(projMargin / sigmaM),
141:     remaining_factor: remainingFactor,
142:   };
143: }
