    """把 PWA 形状的注单合并进 bets 表（按 ref 去重）。"""
    added = skipped = 0
    for row in rows or []:
        if not isinstance(row, dict) or not row.get("game_id") or not row.get("market") or not row.get("side"):
            skipped += 1
            continue
