// WebDAV client for APK (CapacitorHttp) — 浏览器里会被 CORS 拦，仅 APK 可用
const DAV_KEY = "nbaq:dav";
function davCfg() { try { return JSON.parse(localStorage.getItem(DAV_KEY) || "null"); } catch { return null; } }
function davSave(cfg) { localStorage.setItem(DAV_KEY, JSON.stringify(cfg)); }
function davEnabled() { const c = davCfg(); return !!(c && c.user && c.pass); }
async function davFetch(path, opts = {}) {
  const cfg = davCfg();
  const base = (cfg.url || "https://dav.jianguoyun.com/dav/");
  const headers = { Authorization: "Basic " + btoa(cfg.user + ":" + cfg.pass), ...(opts.headers || {}) };
  const resp = await fetch(base + path, { ...opts, headers });
  return resp;
}
async function davGetText(path) { const r = await davFetch(path); if (r.status === 404) return null; if (!r.ok) throw new Error("WebDAV " + r.status); return r.text(); }
async function davPutText(path, text) { const r = await davFetch(path, { method: "PUT", headers: {"Content-Type": "application/json"}, body: text }); if (!r.ok) throw new Error("WebDAV PUT " + r.status); }
