  const away = comp.competitors.find(c=>c.homeAway==="away");
  const homeName = home.team.displayName, awayName = away.team.displayName;
  const bookmakers = (comp.odds||[]).map(o => {
    const markets = [];
    const outcomes = [];
    // spreads
    const ps = o.pointSpread || {};
    for (const [side, name] of [["home", homeName], ["away", awayName]]) {
      const close = (ps[side]||{}).close || {};
      let point = close.line != null ? Number(close.line) : (side==="home" ? Number(o.spread) : (o.spread!=null? -Number(o.spread): null));
      const price = close.odds != null ? Number(String(close.odds).replace("+","")) : null;
      if (point != null && price != null) outcomes.push({name, price, point});
    }
    if (outcomes.length) markets.push({key: "spreads", outcomes});
    // totals
    const t = o.total || {};
    const to = [], line = o.overUnder != null ? Number(o.overUnder) : ((t.over||{}).close||{}).line ?? ((t.under||{}).close||{}).line;
    ...
    // h2h
    const ml = o.moneyline || {};
    const h2h = [];
    for (const [side, name] of [["home",homeName],["away",awayName]]) {
      const price = ((ml[side]||{}).close||{}).odds;
