{
  "name": "nbaq-mobile",
  "version": "1.0.0",
  "private": true,
  "description": "NBA Quant Android shell (Capacitor). www/ is generated from ../site by build.ps1.",
  "dependencies": {
    "@capacitor/android": "^7.4.3",
    "@capacitor/core": "^7.4.3"
  },
  "devDependencies": {
    "@capacitor/cli": "^7.4.3"
  }
}

{
  "appId": "com.gem08166.nbaq",
  "appName": "NBA Quant",
  "webDir": "www",
  "plugins": {
    "CapacitorHttp": {
      "enabled": true
    }
  },
  "android": {
    "allowMixedContent": true
  },
  "server": {
    "androidScheme": "https"
  }
}

# NBA Quant APK 一键构建脚本（Capacitor + Android SDK）
# 用法：
#   .\build.ps1              # 全流程：拷贝 www → sync → 打 debug APK
#   .\build.ps1 -SkipWeb     # 跳过 www 拷贝（只重打包）
param(
    [switch]$SkipWeb
)
$ErrorActionPreference = "Stop"

# --- 环境 ---
$env:Path = [System.Environment]::GetEnvironmentVariable("Path", "Machine") + ";" +
            [System.Environment]::GetEnvironmentVariable("Path", "User") + ";" + $env:Path
$sdk = "$env:LOCALAPPDATA\Android\Sdk"
if (-not (Test-Path $sdk)) { throw "Android SDK 不存在：$sdk" }
$env:ANDROID_HOME = $sdk
$env:ANDROID_SDK_ROOT = $sdk

$jdk = Get-ChildItem "C:\Program Files\Eclipse Adoptium" -Directory -ErrorAction SilentlyContinue |
    Where-Object { $_.Name -like "jdk-17*" } | Sort-Object Name -Descending | Select-Object -First 1
if ($jdk) { $env:JAVA_HOME = $jdk.FullName }
elseif (-not $env:JAVA_HOME) { throw "找不到 JDK 17，请安装：winget install EclipseAdoptium.Temurin.17.JDK" }
Write-Output "JAVA_HOME = $env:JAVA_HOME"
Write-Output "ANDROID_HOME = $env:ANDROID_HOME"

# --- 1. npm 依赖 ---
if (-not (Test-Path "$PSScriptRoot\node_modules")) {
    Write-Output "== npm install =="
    Push-Location $PSScriptRoot
    npm install --no-audit --no-fund
    if ($LASTEXITCODE -ne 0) { Pop-Location; throw "npm install 失败" }
    Pop-Location
}

# --- 2. 拷贝静态站到 www ---
if (-not $SkipWeb) {
    Write-Output "== copy site -> www =="
    $www = "$PSScriptRoot\www"
    if (Test-Path $www) { Remove-Item $www -Recurse -Force }
    robocopy "$PSScriptRoot\..\site" $www /E /NFL /NDL /NJH /NJS /NP | Out-Null
    if ($LASTEXITCODE -ge 8) { throw "robocopy 失败（exit $LASTEXITCODE）" }
}

# --- 3. Capacitor android 工程 ---
if (-not (Test-Path "$PSScriptRoot\android")) {
    Write-Output "== cap add android =="
    Push-Location $PSScriptRoot
    npx cap add android
    if ($LASTEXITCODE -ne 0) { Pop-Location; throw "cap add 失败" }
    Pop-Location
}
Write-Output "== cap sync =="
Push-Location $PSScriptRoot
npx cap sync android
if ($LASTEXITCODE -ne 0) { Pop-Location; throw "cap sync 失败" }
Pop-Location

# --- 4. gradle 打 debug APK ---
Write-Output "== gradlew assembleDebug =="
Push-Location "$PSScriptRoot\android"
.\gradlew assembleDebug --no-daemon
if ($LASTEXITCODE -ne 0) { Pop-Location; throw "gradle 构建失败" }
Pop-Location

$apk = "$PSScriptRoot\android\app\build\outputs\apk\debug\app-debug.apk"
if (Test-Path $apk) {
    Copy-Item $apk "$PSScriptRoot\nbaq-debug.apk" -Force
    Write-Output "== 完成：$PSScriptRoot\nbaq-debug.apk =="
} else {
    throw "没找到 APK：$apk"
}

# NBA Quant APK build script (Capacitor + Android SDK). ASCII only on purpose:
# Windows PowerShell 5.1 parses BOM-less files as ANSI and breaks on Chinese text.
# Usage:
#   .\build.ps1              # full: copy www -> sync -> assembleDebug
#   .\build.ps1 -SkipWeb     # skip www copy (repackage only)
param(
    [switch]$SkipWeb
)
$ErrorActionPreference = "Stop"

# --- environment ---
