      /* 已存在/无权限忽略 */
    }
  }
  resp = await davFetch(path, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: text,
  });
  if (!resp.ok) throw new Error("WebDAV PUT " + resp.status);
  return true;
